package com.enterpriseflow.entity;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="tasks") public class Task { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) private Project project; @Column(nullable=false,length=200) private String title; @Column(columnDefinition="TEXT") private String description; @Column(nullable=false,length=32) private String status="TODO"; @Column(nullable=false,length=32) private String priority="MEDIUM"; @ManyToOne(fetch=FetchType.LAZY) private User assignee; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) private User creator; private LocalDate dueDate; private Instant createdAt; private Instant updatedAt; protected Task(){} public Task(Project p,String t,String d,String priority,User a,User c,LocalDate due){project=p;title=t;description=d;this.priority=priority;assignee=a;creator=c;dueDate=due;} @PrePersist void c(){createdAt=updatedAt=Instant.now();}@PreUpdate void u(){updatedAt=Instant.now();} public UUID getId(){return id;} public Project getProject(){return project;} public String getTitle(){return title;} public String getDescription(){return description;} public String getStatus(){return status;} public String getPriority(){return priority;} public User getAssignee(){return assignee;} public User getCreator(){return creator;} public LocalDate getDueDate(){return dueDate;} public Instant getCreatedAt(){return createdAt;} public void update(String t,String d,String s,String p,User a,LocalDate due){title=t;description=d;status=s;priority=p;assignee=a;dueDate=due;} }
